    public static function key(string $source):string{return 'sepa_order_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {
        $english=explode('-',$locale,2)[0]==='en';$messages=[];foreach(self::ENGLISH as$source=>$translation)$messages[self::key($source)]=$english?$translation:$source;return $messages;
    }
    public static function text(string $source,array $messages):string{return $messages[self::key($source)]??ContributionDeliveryMessages::text($source,$messages);}
